import{_ as t,o as e,c as r,a5 as s}from"./chunks/framework.bIR-4glx.js";const f=JSON.parse('{"title":"实践路线图：创业、自律与 AI","description":"按当前问题选择英语、AI、创业或自律路径，用四周的最小实践留下作品、反馈与下一步决定。","frontmatter":{"title":"实践路线图：创业、自律与 AI","description":"按当前问题选择英语、AI、创业或自律路径，用四周的最小实践留下作品、反馈与下一步决定。","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"practice.md","filePath":"practice.md","lastUpdated":1789776000000}'),d={name:"practice.md"};function i(h,a,n,p,l,o){return e(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="实践路线图-创业、自律与-ai" tabindex="-1">实践路线图：创业、自律与 AI <a class="header-anchor" href="#实践路线图-创业、自律与-ai" aria-label="Permalink to &quot;实践路线图：创业、自律与 AI&quot;">​</a></h1><p>这张路线图补充<a href="./threads/part-0/reader-guide">阅读指南</a>，把书中的方法用于创业、自律与 AI 的具体任务。全书的长期安排见<a href="./threads/part-5/90-day-plan">九十天行动篇</a>；这里的四周只是其中一个可缩放的小实验。你不必先读完，也不必同时开始英语、创业和 AI 三个项目。先选一个本周真实存在的问题，把阅读变成一次可以结束的行动。</p><h2 id="按你现在的问题选一条路" tabindex="-1">按你现在的问题选一条路 <a class="header-anchor" href="#按你现在的问题选一条路" aria-label="Permalink to &quot;按你现在的问题选一条路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你现在的状态</th><th>从哪里读</th><th>本周留下什么</th></tr></thead><tbody><tr><td>想用 AI 学会一项新技能</td><td><a href="./threads/part-3/1-ai-learning">使用 AI 学习一切</a> → <a href="./threads/practice/ai-workflows">AI 工作流</a></td><td>一份独立完成的作品和错误记录</td></tr><tr><td>已经用 AI，但不知道结果靠不靠谱</td><td><a href="./threads/practice/ai-evaluation">AI 评测与可靠性</a> → <a href="./templates/ai-evaluation">评测记录</a></td><td>一个小样本集和一次有依据的版本比较</td></tr><tr><td>有创业想法，尚未接触客户</td><td><a href="./threads/practice/customer-discovery">从问题到首批用户</a> → <a href="./templates/startup-experiment">创业实验卡</a></td><td>真实访谈记录及支持、反对假设的证据</td></tr><tr><td>有人愿意用，但忙而不赚钱</td><td><a href="./threads/practice/sustainable-business">可持续的小生意</a></td><td>一份包含沟通、返工和支持工时的交付账</td></tr><tr><td>开始困难，或中断后想重新开始</td><td><a href="./threads/practice/discipline-and-consistency">自律与坚持实操</a> → <a href="./templates/consistency-plan">持续行动计划</a></td><td>一个明确触发条件、一次缩小范围后的行动和可核对的输出</td></tr><tr><td>英语妨碍阅读或交流</td><td><a href="./threads/part-1/0-cefr">CEFR 目标与自测</a> → <a href="./templates/english-diagnostic">英语诊断</a></td><td>一段录音或一篇短文，标出最需要练习的一项</td></tr></tbody></table><p>表中的产出只是起步建议，不是对所有人的统一考核。照护、轮班或临时事务占用了时间，就减少任务数量，保留一个明确的完成标准。</p><h2 id="一条四周实践路径" tabindex="-1">一条四周实践路径 <a class="header-anchor" href="#一条四周实践路径" aria-label="Permalink to &quot;一条四周实践路径&quot;">​</a></h2><p>这是一份可调整的安排，不承诺四周获得收入或掌握一门技能。每周安排两次 25 分钟的任务和一次 10 分钟复盘，也可以把一周拆成更长的周期。</p><h3 id="第一周-建立起点" tabindex="-1">第一周：建立起点 <a class="header-anchor" href="#第一周-建立起点" aria-label="Permalink to &quot;第一周：建立起点&quot;">​</a></h3><p>填写 <a href="./templates/learning-state">学习状态</a>，只写一个问题。保存一次当前表现：不用 AI 写一段解释、记录现有流程需要的时间，或询问一位用户最近一次遇到的困难。若只得到“应该会有人需要”，起点仍然是一个假设。</p><h3 id="第二周-做最小版本" tabindex="-1">第二周：做最小版本 <a class="header-anchor" href="#第二周-做最小版本" aria-label="Permalink to &quot;第二周：做最小版本&quot;">​</a></h3><p>选一个可以当场演示的输出。学英语可以完成一封真实用途的邮件；创业可以人工交付一个很小的服务；AI 项目可以整理一份带来源的资料摘要。需要 AI 协作时，用 <a href="./templates/ai-task-brief">AI 任务简报</a> 固定输入、边界和验收标准；验证创业想法时，用 <a href="./templates/startup-experiment">创业实验卡</a> 先写清假设与停止条件，先完成一个闭环。</p><h3 id="第三周-让现实给反馈" tabindex="-1">第三周：让现实给反馈 <a class="header-anchor" href="#第三周-让现实给反馈" aria-label="Permalink to &quot;第三周：让现实给反馈&quot;">​</a></h3><p>把输出交给真实使用者，或在新材料上独立复测。记录对方做了什么、卡在哪里，而不只记录“很好”。AI 项目加入缺失信息、冲突来源、工具失败等案例；创业实验记录未回复、拒绝和没有复购的理由。</p><h3 id="第四周-决定保留什么" tabindex="-1">第四周：决定保留什么 <a class="header-anchor" href="#第四周-决定保留什么" aria-label="Permalink to &quot;第四周：决定保留什么&quot;">​</a></h3><p>用 <a href="./templates/weekly-review">每周复盘</a> 比较起点和当前证据。选择继续、缩小、换方法或停止，把决定和理由写下来。只留下下一轮最有价值的一件事。愿意停止一个被反证的方案，同样是进步。</p><h2 id="所有主题共用一套证据" tabindex="-1">所有主题共用一套证据 <a class="header-anchor" href="#所有主题共用一套证据" aria-label="Permalink to &quot;所有主题共用一套证据&quot;">​</a></h2><p>建立一个本地文件夹即可，不需要先搭建复杂的知识库：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-practice/</span></span>
<span class="line"><span>  state.md       当前问题、基线、下一步</span></span>
<span class="line"><span>  attempts/      每次作品、测试或交付</span></span>
<span class="line"><span>  feedback.md    用户反馈、错误与来源</span></span>
<span class="line"><span>  review.md      本周决定和下次开始的位置</span></span></code></pre></div><p>保存对自己有用的最少材料；涉及他人的信息先取得允许并去除不必要的身份细节。公开分享作品时，不把客户材料、聊天记录或密钥一并公开。</p><p>判断记录有没有用，只问两个问题：明天能否接着做？一个月后能否解释为什么这样决定？</p><h2 id="模板工具箱" tabindex="-1">模板工具箱 <a class="header-anchor" href="#模板工具箱" aria-label="Permalink to &quot;模板工具箱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>模板</th></tr></thead><tbody><tr><td>确定当前基线</td><td><a href="./templates/learning-state">学习状态</a>、<a href="./templates/english-diagnostic">英语诊断</a></td></tr><tr><td>与 AI 协作</td><td><a href="./templates/ai-task-brief">任务简报</a>、<a href="./templates/ai-learning-log">学习记录</a>、<a href="./templates/ai-evaluation">评测记录</a></td></tr><tr><td>验证创业想法</td><td><a href="./templates/startup-experiment">创业实验卡</a>、<a href="./templates/ai-project-scorecard">AI 项目评分卡</a></td></tr><tr><td>持续行动与复盘</td><td><a href="./templates/rhythm-ledger">节律账本</a>、<a href="./templates/consistency-plan">持续行动计划</a>、<a href="./templates/weekly-review">每周复盘</a>、<a href="./templates/ai-case-review">AI 经历案例复盘</a></td></tr></tbody></table><p>节律账本安排一周的容量与节奏；持续行动计划细化一个行动实验。模板可以删减。若填写一张表比实际行动耗时更久，就只保留“要做什么、完成证据、下一步”三项。</p><h2 id="如何看待指南中的内容" tabindex="-1">如何看待指南中的内容 <a class="header-anchor" href="#如何看待指南中的内容" aria-label="Permalink to &quot;如何看待指南中的内容&quot;">​</a></h2><p>方法章节提供可以尝试和检验的流程；作者故事记录特定处境中的经验；外部研究和产品资料应沿来源继续核验。文中的示例数字、两周周期和样本数量，除非明确说明，都是帮助开始的设计示例，不代表科学阈值或经营保证。</p><p>想了解背景，可以读 <a href="./threads/part-2/entrepreneurship">创业篇</a> 和 <a href="./threads/part-2/my-story">我的故事</a>。需要行动时，回到所选路径，完成第一份作品。</p>`,26)])])}const m=t(d,[["render",i]]);export{f as __pageData,m as default};
